INSERT INTO `beneficios` VALUES (1, 'CASTROL', 15, 0, 'Aprovecha el precio incluye S/ 20 de descuentos para instalación.\r\n✅ Precio al contado.\r\n✅ También disponible con financiamiento, con un 10% adicional.\r\n✅ La inicial del 50%\r\n Ideal para mantener tu vehículo en óptimas condiciones al mejor precio. 🚗✨', 120.61, 3, 40.20, 'img/beneficios/beneficio_1758140440_68cb1818ab92f.png', 1, '2025-09-17 15:20:40', '2025-09-28 19:29:23');
INSERT INTO `beneficios` VALUES (4, 'CEPSA', 15, 0, 'Aprovecha el precio incluye S/ 20 de descuentos para instalación.\r\n✅ Precio al contado.\r\n✅ También disponible con financiamiento, con un 10% adicional.\r\n✅ La inicial del 50%\r\n Ideal para mantener tu vehículo en óptimas condiciones al mejor precio. 🚗✨', 78.87, 2, 39.43, 'img/beneficios/beneficio_1759105695_68d9d29fe237e.png', 1, '2025-09-17 15:47:32', '2025-09-28 19:28:15');
INSERT INTO `beneficios` VALUES (6, 'REDMI NOTE 14', 2, NULL, 'Ahora puedes acceder al nuevo Redmi Note 14, un smartphone potente, confiable y perfecto para trabajar con el aplicativo sin interrupciones. 🚗💨\r\n💡 No dejes pasar esta oportunidad. Renueva tu celular y sigue creciendo con nosotros.', 300.00, 6, 100.00, 'img/beneficios/beneficio_1759104805_68d9cf25d6ea6.png', 1, '2025-09-28 19:13:25', '2025-09-28 19:13:25');
INSERT INTO `beneficios` VALUES (7, 'REDMI NOTE 14 PRO', 3, 0, 'Pensamos en el crecimiento de nuestros clientes, por eso ofrecemos el nuevo Redmi Note 14 pro, un equipo moderno y potente para que trabajes con total confianza. 🚗💨\r\n\r\n✅ Cuotas semanales accesibles\r\n\r\n💡 Aprovecha esta oportunidad y lleva tu celular.', 400.00, 6, 130.00, 'img/beneficios/beneficio_1759105325_68d9d12deef8c.png', 1, '2025-09-28 19:22:05', '2025-09-28 19:23:28');
INSERT INTO `beneficios` VALUES (8, 'REDMI NOTE 14 PRO 5G', 4, NULL, 'Pensamos en el crecimiento de nuestros clientes, por eso ofrecemos el nuevo Redmi Note 14 pro 5G, un equipo moderno y potente para que trabajes con total confianza. 🚗💨 ✅ Cuotas semanales accesibles 💡 Aprovecha esta oportunidad y lleva tu celular.', 500.00, 6, 150.00, 'img/beneficios/beneficio_1759105390_68d9d16eb8f8c.png', 1, '2025-09-28 19:23:10', '2025-09-28 19:23:10');
