INSERT INTO `beneficios` VALUES (10, 'LIQUI MOLY', 15, NULL, 'Aprovecha el precio incluye S/ 20 de descuentos para instalación.\r\n✅ Precio al contado.\r\n✅ También disponible con financiamiento, con un 10% adicional.\r\n✅ La inicial del 50%\r\n Ideal para mantener tu vehículo en óptimas condiciones al mejor precio. 🚗✨', 119.73, 3, 39.91, 'img/beneficios/beneficio_1759106055_68d9d4070e601.png', 1, '2025-09-28 19:34:15', '2025-09-28 19:34:15');
